package com.sobrenaturaldirector.mutation.model;

import java.util.*;import com.sobrenaturaldirector.domain.StableId;import com.sobrenaturaldirector.spatial.geometry.LocalAabb;

public final class MutationIntent {private final String id,sourceReference,semanticRequirement;private final MutationIntentType type;private final MutationPhase phase;private final LocalAabb target;private final MutationClass mutationClass;private final RiskClass risk;private final Set<String> preconditions,dependencies;private final String verification;private final RollbackPlan rollback;public MutationIntent(String id,MutationIntentType type,MutationPhase phase,LocalAabb target,String sourceReference,String semanticRequirement,Collection<String> preconditions,Collection<String> dependencies,MutationClass mutationClass,RiskClass risk,String verification,RollbackPlan rollback){this.id=StableId.require(id,"intentId");if(type==null||phase==null||target==null||mutationClass==null||risk==null)throw new IllegalArgumentException("invalid mutation intent");this.type=type;this.phase=phase;this.target=target;this.sourceReference=StableId.require(sourceReference,"sourceReference");this.semanticRequirement=semanticRequirement==null?"":semanticRequirement;this.preconditions=sorted(preconditions);this.dependencies=sorted(dependencies);this.mutationClass=mutationClass;this.risk=risk;this.verification=StableId.require(verification,"verificationRequirement");this.rollback=rollback==null?new RollbackPlan(false,null):rollback;}private static Set<String>sorted(Collection<String>x){return Collections.unmodifiableSet(new TreeSet<String>(x==null?Collections.<String>emptySet():new HashSet<String>(x)));}public String getId(){return id;}public MutationIntentType getType(){return type;}public MutationPhase getPhase(){return phase;}public LocalAabb getTarget(){return target;}public String getSourceReference(){return sourceReference;}public String getSemanticRequirement(){return semanticRequirement;}public Set<String> getPreconditions(){return preconditions;}public Set<String> getDependencies(){return dependencies;}public MutationClass getMutationClass(){return mutationClass;}public RiskClass getRisk(){return risk;}public String getVerification(){return verification;}public RollbackPlan getRollback(){return rollback;}}
